    slug: "recycle-management-early-road-harrisonburg",
    name: "Recycle Management \u2013 Early Road Building",
    location: "Harrisonburg, VA",
    category: "REPLACEMENT",
    roofType: "TPO Overlay",
    systemDescription: "Ballast removal and TPO overlay",
    description: "This building on Early Road in Harrisonburg is owned by Recycle Management and home to Sugarite. It had a very old ballasted rubber roof with a lot of leaks.",
